CREATE SCHEMA IF NOT EXISTS connections;
CREATE TABLE connections.connections(id uuid PRIMARY KEY,host_id uuid NOT NULL,credential_ref_id uuid NOT NULL,name text NOT NULL,protocol text NOT NULL CHECK(protocol IN ('rdp','ssh','vnc')),port integer NOT NULL CHECK(port BETWEEN 1 AND 65535),options jsonb NOT NULL DEFAULT '{}',clipboard_enabled boolean NOT NULL DEFAULT true,file_transfer_enabled boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT true,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(host_id,name));
